function searchContent(query, child, limit) {
  limit = limit || 20;
  var q = (query || "").toLowerCase().trim();
  var tokens = q.split(/\s+/).filter(Boolean);

  var matchedCategories = {};
  for (var i = 0; i < tokens.length; i++) {
    var cats = TOPIC_KEYWORDS[tokens[i]];
    if (cats) cats.forEach(function(c) { matchedCategories[c] = true; });
  }
  var entries = Object.entries(TOPIC_KEYWORDS);
  for (var j = 0; j < entries.length; j++) {
    var phrase = entries[j][0], phraseCats = entries[j][1];
    if (phrase.indexOf(" ") !== -1 && q.indexOf(phrase) !== -1) {
      phraseCats.forEach(function(c) { matchedCategories[c] = true; });
    }
  }

  var results;
  var categoryKeys = Object.keys(matchedCategories);

  if (categoryKeys.length > 0) {
    results = CONTENT_DATABASE.filter(function(item) {
      return matchedCategories[item.category];
    });
  } else {
    results = CONTENT_DATABASE.filter(function(item) {
      return tokens.some(function(t) {
        return item.title.toLowerCase().indexOf(t) !== -1 ||
               item.description.toLowerCase().indexOf(t) !== -1 ||
               item.category.toLowerCase().indexOf(t) !== -1;
      });
    });
    if (results.length === 0) {
      results = CONTENT_DATABASE.filter(function(_, idx) { return idx % 15 === 0; });
    }
  }

  if (child) {
    if (child.max_content_rating === "G") {
      results = results.filter(function(r) { return r.ageRating === "G"; });
    } else if (child.max_content_rating === "PG") {
      results = results.filter(function(r) { return r.ageRating !== "PG-13"; });
    }
    if (child.blocked_keywords && child.blocked_keywords.length > 0) {
      results = results.filter(function(r) {
        return !child.blocked_keywords.some(function(kw) {
          return r.title.toLowerCase().indexOf(kw.toLowerCase()) !== -1 ||
                 r.description.toLowerCase().indexOf(kw.toLowerCase()) !== -1;
        });
      });
    }
  }

  return results.slice(0, limit);
}

module.exports = { CONTENT_DATABASE: CONTENT_DATABASE, TOPIC_KEYWORDS: TOPIC_KEYWORDS, searchContent: searchContent };
